import{_ as a,o,c as r,a3 as t}from"./chunks/framework.DemfeeZg.js";const m=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/configuration.md","filePath":"en/configuration.md","lastUpdated":1789921234000}'),i={name:"en/configuration.md"};function n(l,e,d,c,s,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>This document is deprecated and no longer maintained, because the graphical configuration panel is available. Some of the content below may be outdated.</strong></p><ul><li>Configuration is optional: Twikoo works without it.</li><li>Make sure the <code>config</code> collection is <strong>not</strong> publicly readable, otherwise secrets such as your SMTP password may leak.<br> The default permissions are safe, so you normally do not need to change anything.</li><li>Store all configuration items in a single record.</li></ul></div><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="site-name" tabindex="-1">SITE_NAME <a class="header-anchor" href="#site-name" aria-label="Permalink to &quot;SITE_NAME&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: My Blog</p><p>Name of the blog or site.</p><h3 id="site-url" tabindex="-1">SITE_URL <a class="header-anchor" href="#site-url" aria-label="Permalink to &quot;SITE_URL&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: <a href="https://www.example.com" target="_blank" rel="noreferrer">https://www.example.com</a></p><p>Address of the blog or site.</p><h3 id="blogger-email" tabindex="-1">BLOGGER_EMAIL <a class="header-anchor" href="#blogger-email" aria-label="Permalink to &quot;BLOGGER_EMAIL&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: <a href="mailto:12345@qq.com" target="_blank" rel="noreferrer">12345@qq.com</a></p><p>Email address of the blogger, used for mail notifications and for the blogger badge.</p><h2 id="anti-spam" tabindex="-1">Anti-spam <a class="header-anchor" href="#anti-spam" aria-label="Permalink to &quot;Anti-spam&quot;">​</a></h2><h3 id="akismet-key" tabindex="-1">AKISMET_KEY <a class="header-anchor" href="#akismet-key" aria-label="Permalink to &quot;AKISMET_KEY&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: 8651783ed123</p><p>API key of the anti-spam comment service.</p><h3 id="hide-spam" tabindex="-1">HIDE_SPAM <a class="header-anchor" href="#hide-spam" aria-label="Permalink to &quot;HIDE_SPAM&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>false</code><br> Required: <code>false</code><br> Example: <code>true</code></p><p>When set to <code>true</code>, comments marked as spam are hidden from everyone in the front-end comment area, including administrators and the comment author. They remain visible, reviewable and restorable in the admin panel.</p><h2 id="wechat-notification" tabindex="-1">WeChat notification <a class="header-anchor" href="#wechat-notification" aria-label="Permalink to &quot;WeChat notification&quot;">​</a></h2><h3 id="sc-sendkey" tabindex="-1">SC_SENDKEY <a class="header-anchor" href="#sc-sendkey" aria-label="Permalink to &quot;SC_SENDKEY&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: SCT1364TKdsiGjGvyAZNYDVnuHW12345</p><p><code>SCKEY</code> of the <a href="https://sc.ftqq.com/3.version" target="_blank" rel="noreferrer">ServerChan</a> WeChat push service.</p><h2 id="mail-notification" tabindex="-1">Mail notification <a class="header-anchor" href="#mail-notification" aria-label="Permalink to &quot;Mail notification&quot;">​</a></h2><h3 id="sender-email" tabindex="-1">SENDER_EMAIL <a class="header-anchor" href="#sender-email" aria-label="Permalink to &quot;SENDER_EMAIL&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: <a href="mailto:blog@example.com" target="_blank" rel="noreferrer">blog@example.com</a></p><p>Sender address of mail notifications. For most mail providers <code>SENDER_EMAIL</code> must be identical to <code>SMTP_USER</code>, otherwise sending fails.</p><h3 id="sender-name" tabindex="-1">SENDER_NAME <a class="header-anchor" href="#sender-name" aria-label="Permalink to &quot;SENDER_NAME&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: My Blog comment notification</p><p>Subject/title of mail notifications.</p><h3 id="smtp-service" tabindex="-1">SMTP_SERVICE <a class="header-anchor" href="#smtp-service" aria-label="Permalink to &quot;SMTP_SERVICE&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: qiye.aliyun</p><p>Mail provider used for notifications.<br> See the full list: <a href="https://nodemailer.com/smtp/well-known/#supported-services" target="_blank" rel="noreferrer">Supported services</a></p><h3 id="smtp-user" tabindex="-1">SMTP_USER <a class="header-anchor" href="#smtp-user" aria-label="Permalink to &quot;SMTP_USER&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: <a href="mailto:blog@example.com" target="_blank" rel="noreferrer">blog@example.com</a></p><p>Username of the mail account.</p><h3 id="smtp-pass" tabindex="-1">SMTP_PASS <a class="header-anchor" href="#smtp-pass" aria-label="Permalink to &quot;SMTP_PASS&quot;">​</a></h3><p>Type: <code>String</code><br> Default: <code>null</code><br> Required: <code>false</code><br> Example: password</p><p>Password of the mail account. For QQ Mail, use the authorization code.</p>',39)])])}const u=a(i,[["render",n]]);export{m as __pageData,u as default};
